 hurt(damage){if(this.dead||this.invincible>0)return;this.hp=Math.max(0,this.hp-damage/(this.effects.armor||1));this.invincible=1.25;this.flash=.15;this.shake=9;this.event('hit');if(this.hp<=0){if(this.effects.life&&!this.reviveUsed){this.hp=100;this.invincible=4;this.reviveUsed=true;this.event('revive');}else{this.dead=true;this.deathTime=0;this.event('Died',1,Math.floor(this.distance));this.particle(PLAYER_X,this.y-40,'#124f81',22);}}}
